module.exports = async function(data) {
  const body = (data.$trigger && data.$trigger.body) || {};
  const email = String(body.email || '').trim().toLowerCase();
  const priceId = String(body.priceId || '').trim();
  const rawPromoCode = body.promotionCode ? String(body.promotionCode).trim() : null;

  if (!email || !priceId) {
    return {
      verified: false,
      verificationStatus: 'unavailable',
      couponState: 'verification_unavailable',
      error: 'Missing required email or priceId.'
    };
  }

  const STRIPE_SECRET_KEY = data.$env.STRIPE_SECRET_KEY;
  const VERIFICATION_SECRET = data.$env.STRIPE_CHECKOUT_VERIFICATION_SECRET || STRIPE_SECRET_KEY;

  async function stripeRequest(path, method, params) {
    const url = 'https://api.stripe.com/v1/' + path;
    const headers = {
      'Authorization': 'Bearer ' + STRIPE_SECRET_KEY,
      'Content-Type': 'application/x-www-form-urlencoded'
    };
    const options = { method, headers };
    if (params && method === 'POST') {
      options.body = new URLSearchParams(params).toString();
    }
    const res = await fetch(method === 'GET' && params ? url + '?' + new URLSearchParams(params).toString() : url, options);
    const json = await res.json();
    if (!res.ok) {
      const err = new Error((json.error && json.error.message) || 'Stripe API error');
      err.code = (json.error && json.error.code) || 'stripe_error';
      throw err;
    }
    return json;
  }

  // 1. Fetch authoritative Stripe Price + Product
  const price = await stripeRequest('prices/' + encodeURIComponent(priceId), 'GET', { 'expand[]': 'product' });
  if (!price || !price.active) {
    return {
      verified: false,
      verificationStatus: 'unavailable',
      couponState: 'verification_unavailable',
      error: 'Selected price is inactive or unavailable.'
    };
  }

  const originalPrice = Number(price.unit_amount || 0);
  const currency = String(price.currency || 'usd').toLowerCase();
  const interval = (price.recurring && price.recurring.interval) || 'month';
  const productId = typeof price.product === 'string' ? price.product : price.product.id;
  const planName = (typeof price.product === 'object' && price.product.name) || price.nickname || 'Subscription Plan';

  // 2. Look up existing Stripe customer by email (if any)
  const customers = await stripeRequest('customers', 'GET', { email, limit: '1' });
  const customer = customers.data && customers.data[0] ? customers.data[0] : null;

  // 3. Resolve and validate Promotion Code if provided
  let promoObj = null;
  let couponObj = null;
  let couponState = 'not_applied';

  if (rawPromoCode) {
    const promoList = await stripeRequest('promotion_codes', 'GET', {
      code: rawPromoCode,
      active: 'true',
      limit: '1',
      'expand[]': 'data.coupon.applies_to'
    });
    promoObj = promoList.data && promoList.data[0] ? promoList.data[0] : null;
    if (!promoObj || !promoObj.active || !promoObj.coupon || !promoObj.coupon.valid) {
      return {
        verified: false,
        verificationStatus: 'unverified',
        couponState: 'invalid_or_ineligible',
        priceId,
        planName,
        interval,
        currency,
        originalPrice,
        subtotal: originalPrice,
        discountAmount: 0,
        tax: 0,
        amountDueToday: originalPrice,
        renewalAmount: originalPrice
      };
    }

    couponObj = promoObj.coupon;
    const nowSec = Math.floor(Date.now() / 1000);
    if (promoObj.expires_at && promoObj.expires_at < nowSec) {
      return { verified: false, verificationStatus: 'unverified', couponState: 'invalid_or_ineligible', priceId };
    }
    if (promoObj.max_redemptions && promoObj.times_redeemed >= promoObj.max_redemptions) {
      return { verified: false, verificationStatus: 'unverified', couponState: 'invalid_or_ineligible', priceId };
    }
    if (couponObj.applies_to && Array.isArray(couponObj.applies_to.products) && couponObj.applies_to.products.length > 0) {
      if (!couponObj.applies_to.products.includes(productId)) {
        return { verified: false, verificationStatus: 'unverified', couponState: 'invalid_or_ineligible', priceId };
      }
    }
    if (promoObj.restrictions && promoObj.restrictions.minimum_amount) {
      if (originalPrice < promoObj.restrictions.minimum_amount) {
        return { verified: false, verificationStatus: 'unverified', couponState: 'invalid_or_ineligible', priceId };
      }
    }
    if (promoObj.restrictions && promoObj.restrictions.first_time_transaction && customer) {
      const invoices = await stripeRequest('invoices', 'GET', { customer: customer.id, status: 'paid', limit: '1' });
      if (invoices.data && invoices.data.length > 0) {
        return { verified: false, verificationStatus: 'unverified', couponState: 'invalid_or_ineligible', priceId };
      }
    }
    couponState = 'verified_applied';
  }

  // 4. Create authoritative Stripe Invoice Preview
  const previewParams = {
    'subscription_details[items][0][price]': priceId,
    'subscription_details[items][0][quantity]': '1'
  };
  if (customer) {
    previewParams['customer'] = customer.id;
  } else {
    previewParams['currency'] = currency;
  }
  if (promoObj) {
    previewParams['discounts[0][promotion_code]'] = promoObj.id;
  }

  let invoicePreview;
  try {
    invoicePreview = await stripeRequest('invoices/create_preview', 'POST', previewParams);
  } catch (err) {
    if (rawPromoCode) {
      return {
        verified: false,
        verificationStatus: 'unverified',
        couponState: 'invalid_or_ineligible',
        priceId,
        error: 'Promotion code cannot be applied to this plan.'
      };
    }
    throw err;
  }

  const subtotal = Number(invoicePreview.subtotal ?? originalPrice);
  const totalDiscount = Array.isArray(invoicePreview.total_discount_amounts)
    ? invoicePreview.total_discount_amounts.reduce((acc, d) => acc + Number(d.amount || 0), 0)
    : Math.max(0, subtotal - Number(invoicePreview.total ?? subtotal));
  const tax = Number(invoicePreview.tax ?? 0);
  const amountDueToday = Number(invoicePreview.amount_due ?? invoicePreview.total ?? Math.max(0, subtotal - totalDiscount + tax));
  const renewalAmount = couponObj && couponObj.duration === 'forever' ? amountDueToday : originalPrice;

  // Verify that if a promotion code was requested, Stripe actually applied the discount to the preview
  if (promoObj && totalDiscount <= 0 && amountDueToday >= originalPrice && (couponObj.percent_off > 0 || couponObj.amount_off > 0)) {
    return {
      verified: false,
      verificationStatus: 'unverified',
      couponState: 'invalid_or_ineligible',
      priceId,
      error: 'Discount did not apply to the invoice preview.'
    };
  }

  const crypto = require('crypto');
  const issuedAt = Date.now();
  const payloadStr = [email, priceId, promoObj ? promoObj.id : 'none', amountDueToday, currency, issuedAt].join('|');
  const signature = crypto.createHmac('sha256', VERIFICATION_SECRET).update(payloadStr).digest('hex').slice(0, 32);
  const verificationReference = 'vref_1_' + Buffer.from(payloadStr).toString('base64url') + '.' + signature;

  return {
    verified: true,
    verificationStatus: 'verified',
    couponState,
    priceId,
    planName,
    interval,
    currency,
    originalPrice,
    subtotal,
    discountAmount: totalDiscount,
    tax,
    amountDueToday,
    renewalAmount,
    promotionCode: rawPromoCode,
    promotionCodeId: promoObj ? promoObj.id : null,
    promotionName: couponObj ? (couponObj.name || rawPromoCode) : null,
    percentOff: couponObj ? (couponObj.percent_off ?? null) : null,
    amountOff: couponObj ? (couponObj.amount_off ?? null) : null,
    duration: couponObj ? (couponObj.duration ?? null) : null,
    durationInMonths: couponObj ? (couponObj.duration_in_months ?? null) : null,
    verificationReference,
    verifiedAt: issuedAt
  };
};

module.exports = async function(data) {
  const body = (data.$trigger && data.$trigger.body) || {};
  const email = String(body.email || '').trim().toLowerCase();
  const name = String(body.name || email).trim();
  const priceId = String(body.priceId || '').trim();
  const promotionCodeId = (body.promotionCodeId || body.promoCodeId) ? String(body.promotionCodeId || body.promoCodeId).trim() : null;
  const approvedAmountDue = typeof body.approvedAmountDue === 'number' ? body.approvedAmountDue : null;
  const approvedCurrency = body.approvedCurrency ? String(body.approvedCurrency).toLowerCase() : 'usd';
  const verificationReference = body.verificationReference ? String(body.verificationReference) : null;
  const idempotencyKey = body.idempotencyKey ? String(body.idempotencyKey) : null;

  if (!email || !priceId || approvedAmountDue === null || approvedAmountDue < 0) {
    throw new Error('VERIFICATION_REQUIRED: Missing email, priceId, or approvedAmountDue.');
  }

  const STRIPE_SECRET_KEY = data.$env.STRIPE_SECRET_KEY;

  async function stripeRequest(path, method, params, idempKey) {
    const url = 'https://api.stripe.com/v1/' + path;
    const headers = {
      'Authorization': 'Bearer ' + STRIPE_SECRET_KEY,
      'Content-Type': 'application/x-www-form-urlencoded'
    };
    if (idempKey && method === 'POST') {
      headers['Idempotency-Key'] = idempKey;
    }
    const options = { method, headers };
    if (params && method === 'POST') {
      options.body = new URLSearchParams(params).toString();
    }
    const res = await fetch(method === 'GET' && params ? url + '?' + new URLSearchParams(params).toString() : url, options);
    const json = await res.json();
    if (!res.ok) {
      const err = new Error((json.error && json.error.message) || 'Stripe API error');
      err.code = (json.error && json.error.code) || 'stripe_error';
      throw err;
    }
    return json;
  }

  // 1. Find or create Customer
  const customers = await stripeRequest('customers', 'GET', { email, limit: '1' });
  let customer = customers.data && customers.data[0] ? customers.data[0] : null;
  if (!customer) {
    customer = await stripeRequest('customers', 'POST', { email, name });
  }

  // 2. Build Subscription creation params
  const subParams = {
    customer: customer.id,
    'items[0][price]': priceId,
    payment_behavior: 'default_incomplete',
    'payment_settings[save_default_payment_method]': 'on_subscription',
    'expand[0]': 'latest_invoice.payment_intent',
    'expand[1]': 'latest_invoice.discounts',
    'expand[2]': 'pending_setup_intent'
  };
  if (promotionCodeId) {
    subParams['discounts[0][promotion_code]'] = promotionCodeId;
  }

  const sub = await stripeRequest('subscriptions', 'POST', subParams, idempotencyKey);
  const latestInvoice = sub.latest_invoice && typeof sub.latest_invoice === 'object' ? sub.latest_invoice : null;
  const invoiceAmountDue = latestInvoice && typeof latestInvoice.amount_due === 'number' ? latestInvoice.amount_due : null;
  const invoiceSubtotal = latestInvoice && typeof latestInvoice.subtotal === 'number' ? latestInvoice.subtotal : null;
  const invoiceCurrency = latestInvoice && latestInvoice.currency ? String(latestInvoice.currency).toLowerCase() : approvedCurrency;
  const invoiceTotalDiscount = latestInvoice && Array.isArray(latestInvoice.total_discount_amounts)
    ? latestInvoice.total_discount_amounts.reduce((acc, d) => acc + Number(d.amount || 0), 0)
    : 0;

  const paymentIntent = latestInvoice && latestInvoice.payment_intent && typeof latestInvoice.payment_intent === 'object'
    ? latestInvoice.payment_intent
    : null;
  const pendingSetupIntent = sub.pending_setup_intent && typeof sub.pending_setup_intent === 'object'
    ? sub.pending_setup_intent
    : null;

  // 3. Enforce Charge Protection BEFORE returning any clientSecret
  const discountApplied = promotionCodeId ? (invoiceTotalDiscount > 0 || invoiceAmountDue === 0) : false;
  const hasChargeableIntentForZeroApproval = approvedAmountDue === 0 && ((paymentIntent && paymentIntent.amount > 0) || (invoiceAmountDue !== null && invoiceAmountDue > 0));
  const exceedsApproved = invoiceAmountDue === null || invoiceAmountDue > approvedAmountDue;
  const currencyMismatch = invoiceCurrency !== approvedCurrency;
  const missingPromoDiscount = Boolean(promotionCodeId) && !discountApplied;

  if (hasChargeableIntentForZeroApproval || exceedsApproved || currencyMismatch || missingPromoDiscount) {
    // Immediately cancel incomplete subscription so no charge can ever occur
    try {
      await stripeRequest('subscriptions/' + encodeURIComponent(sub.id), 'DELETE');
    } catch (_) {}

    return {
      aborted: true,
      subscriptionId: sub.id,
      clientSecret: null,
      requiresSetup: false,
      invoiceAmountDue,
      invoiceSubtotal,
      invoiceDiscountAmount: invoiceTotalDiscount,
      invoiceCurrency,
      appliedPromotionCodeId: discountApplied ? promotionCodeId : null,
      discountApplied,
      verificationReference
    };
  }

  // 4. Determine clientSecret (SetupIntent for $0.00 if card collection needed, or PaymentIntent for > $0)
  let clientSecret = null;
  let requiresSetup = false;
  if (approvedAmountDue === 0) {
    if (pendingSetupIntent && pendingSetupIntent.client_secret) {
      clientSecret = pendingSetupIntent.client_secret;
      requiresSetup = true;
    } else {
      clientSecret = null;
      requiresSetup = false;
    }
  } else if (paymentIntent && paymentIntent.client_secret) {
    clientSecret = paymentIntent.client_secret;
    requiresSetup = false;
  }

  return {
    subscriptionId: sub.id,
    clientSecret,
    requiresSetup,
    invoiceAmountDue,
    invoiceSubtotal,
    invoiceDiscountAmount: invoiceTotalDiscount,
    invoiceCurrency,
    appliedPromotionCodeId: promotionCodeId,
    discountApplied,
    verificationReference
  };
};
